 for slot in slots:solution=solution.replace('{{}}',slot['answer'],1)
 assert template.count('{{}}')==len(slots)
 rows.append(dict(id=f'{key}-{len(rows)+1}',title=title,goal=goal,code=template,solution=solution,slots=slots,hint=hint,context='',taskIndex=task,examComments='原题任务：'+courses[key]['tasks'][task]['title']))
